mapper.select:
select pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, scc.* from SYS_Sequence_Current_Code scc left join Pre_Project pro on pro.P_Id=scc.P_Id left join Sec_Info sec on sec.Sec_Id=scc.Sec_Id left join Con_Contract con on con.Con_Id=scc.Con_Id where scc.S_Id=#{params.sId}
order by scc.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by scc.Cc_No desc
limit #{params.start},#{params.size}
